def canonical_red_path(L, side):
    if L == 1:
        return [(0, 0), (1, 0)]
    m = (L - 1) // 2
    pos = [(0, 0)]
    pos.append((0, side))
    for i in range(1, m + 1):
        pos.append((i, side))
    for i in range(m, 0, -1):
        pos.append((i, 0))
    return pos

def map_red(p, v):
    x, y = p
    if v == (1, 0):
        return (x, y)
    if v == (-1, 0):
        return (-x, y)
    if v == (0, 1):
        return (-y, x)
    return (y, -x)  # (0, -1)

def red_expanded_steps(v, L, side):
    pos = canonical_red_path(L, side)
    mapped = [map_red(p, v) for p in pos]
    return [
        (mapped[i + 1][0] - mapped[i][0], mapped[i + 1][1] - mapped[i][1])
        for i in range(L)
    ]

